const item = $('Text Pipeline Input').first().json;
const order = item.order || {};
const hasApprovedStoryBrief = Boolean(String(order.approvedStoryBrief || '').trim());
const approvedArtifactCanon = hasApprovedStoryBrief ? String(order.approvedArtifactCanon || '').replace(/\s+/g, ' ').trim().slice(0, 700) : '';
const legacyArtifact = hasApprovedStoryBrief ? '' : String(order.artifact || '').replace(/\s+/g, ' ').trim().slice(0, 350);
const effectiveArtifactCanon = approvedArtifactCanon || legacyArtifact;
const jobId = item.jobId || 'ft_' + Date.now();
const requestedWorldKey = order.world || 'romantic_story';
const worldAliases = { new_year: 'hogwarts_world', disney_light: 'romantic_story' };
const worldKey = worldAliases[requestedWorldKey] || requestedWorldKey;
const chaptersTarget = Math.max(1, Math.min(8, Number(order.chapters || 5)));
const lengthTarget = Math.max(2500, Number(order.lengthTarget || 19500));
const chapterTextBlockTargets = { 1: 4, 2: 4, 3: 6, 4: 6, 5: 5 };
const firstChapterTextBlockTarget = chapterTextBlockTargets[1] || 4;
const chapterNumbers = Array.from({ length: chaptersTarget }, (_, index) => index + 1);
const planShape = chapterNumbers.map((n) => '{ "n": ' + n + ', "title": "...", "beat": "...", "visualBrief": "...", "heroNumbers": [1], "shotType": "...", "physicalPlacement": "...", "spatialRelations": [], "forbiddenMisreads": [], "useArtifactCanon": false, "artifactRole": "", "requiredObjects": [], "objectScale": "", "forbiddenElements": [] }').join(', ');
const laterChaptersText = chaptersTarget > 1 ? 'краткий план 2-' + chaptersTarget + ' глав' : 'только финальный вектор истории без дополнительных глав';
const activeHeroes = (order.heroes || []).filter((hero) => hero.name || hero.description || hero.relation || hero.hasPhoto);
const heroCount = activeHeroes.length;
const hasChildHero = activeHeroes.some((hero) => hero.ageGroup === 'child');
const childTonePolicy = hasChildHero
  ? 'ОБЯЗАТЕЛЬНЫЙ ПРИОРИТЕТ: среди героев есть ребенок. Вся история должна быть светлой, жизнеутверждающей и эмоционально безопасной. Допустимы загадка, волнение и преодолимые препятствия, но запрещены смерть, жестокость, пытки, безысходность, предательство близких, травмирующее преследование, хоррор и глобальная катастрофа. После напряжения давай передышку, поддержку или юмор; финал теплый, завершенный и обнадеживающий. Это правило важнее жанровой атмосферы.'
  : 'История может содержать жанровое напряжение, но должна сохранять человеческое тепло, эмоциональные передышки и завершенный обнадеживающий финал.';
const protagonistMode = heroCount <= 1 ? 'solo' : (heroCount === 2 ? 'duo' : 'ensemble');
function protagonistPolicyFor(mode) {
  if (mode === 'solo') {
    const heroName = activeHeroes[0]?.name || 'главный герой';
    return 'SOLO: история про одного главного героя (' + heroName + '). Не добавляй второго постоянного главного героя, романтического партнера, напарника, спутника или co-hero, который проходит весь сюжет рядом. Допустимы только эпизодические встречные персонажи: продавец, проводник, родственник, случайный помощник, соперник или голос места; они не получают равную арку и не становятся парой/командой. Драматургия строится через цель героя, место, событие, внутренний выбор, семейную/личную память и изменение отношения героя к себе или задаче.';
  }
  if (mode === 'duo') return 'DUO: два заданных пользователя героя являются центром истории. Не добавляй третьего постоянного спутника. Отношения двигаются между этими двумя героями.';
  return 'ENSEMBLE: все заданные пользователем герои важны. Не добавляй новых постоянных участников команды сверх анкеты пользователя.';
}
const protagonistPolicy = protagonistPolicyFor(protagonistMode);
